"""Convert Sorted Array to Binary Search Tree — pick the middle as the root.

Splitting at the midpoint keeps both sides within one element of each other,
which is exactly the height-balance requirement. LeetCode accepts *any* valid
balanced BST; picking the upper middle reproduces the tree shown in the
examples, which is what the tests here expect.

Time: O(n)   Space: O(log n)
"""
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def sortedArrayToBST(self, nums: List[int]):
        def build(lo: int, hi: int):
            if lo > hi:
                return None
            mid = (lo + hi + 1) // 2
            node = TreeNode(nums[mid])
            node.left = build(lo, mid - 1)
            node.right = build(mid + 1, hi)
            return node

        return build(0, len(nums) - 1)
